import {STORE_KEY,PHASES,GOALS,VENDORS,ISSUES,POLICIES,POLICY_DATE,REPLY_TYPES,escapeHtml as esc,dateOnly,createCase,seedCases,loadCases,saveCases,isClosed,missingEvidence,applicablePolicy,deadline,nextAction,logEvent,invalidateDraft,generateDraft,approveDraft,recordSubmission,addReply,completeCase} from './core.mjs';
import {createPreparationController,doriView,PREPARATION_DELAY_MS} from './dori.mjs';

const paths={
  box:'M4 7 12 3l8 4v10l-8 4-8-4V7Zm0 0 8 4 8-4M12 11v10',
  cases:'M8 5V3h8v2M5 5h14v16H5V5Zm4 5h6M9 14h6M9 18h4',
  calendar:'M5 5h14v16H5V5Zm3-2v4m8-4v4M5 10h14m-10 4h2m3 0h1m-6 3h2',
  plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',file:'M14 3H5v18h14V8l-5-5Zm0 0v6h5M9 13h6m-6 4h6',
  info:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18ZM12 11v6m0-10v1',
  shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',
  close:'m6 6 12 12M6 18 18 6',copy:'M9 8h11v13H9V8Zm-5 8V3h11',clock:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Zm0-14v5l3 2',
  reply:'m8 5-5 5 5 5m-5-5h12a6 6 0 0 1 6 6v3',link:'m10 13 4-4m-6 7-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 0 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',
  upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',refresh:'M20 7a8 8 0 1 0 1 8M20 3v5h-5'
};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;}
const app=document.querySelector('#app'), modal=document.querySelector('#modal'),toast=document.querySelector('#toast');
let cases=[],storageError='',selectedId='',view='cases',tab='evidence',filter='active',toastTimer;
let preparing=null,preparationError=null,previewStill=false;
const preparation=createPreparationController();
const reducedMotion=()=>document.defaultView?.matchMedia?.('(prefers-reduced-motion: reduce)').matches || false;
const sessionFiles=new Map();
try{const loaded=loadCases(localStorage);cases=loaded.cases;if(loaded.fresh)saveCases(localStorage,cases);}catch{storageError='브라우저 저장 데이터를 읽을 수 없어요. 초기화 전에는 기존 데이터를 덮어쓰지 않습니다.';}
selectedId=cases[0]?.id||'';
function selected(){return cases.find(c=>c.id===selectedId);}
function cancelDraftPreparation(reason='cancelled',inform=false){
  if(!preparation.cancel(reason))return false;
  preparing=null;
  if(inform){render();notify('초안 준비를 취소했어요. 기존 사건 상태와 초안은 유지됩니다.');}
  return true;
}
function startDraftPreparation(c){
  if(preparation.running)return;
  if(isClosed(c))throw Error('종료된 사건의 초안을 만들 수 없습니다.');
  if(missingEvidence(c).length)throw Error('필수 자료의 보유 여부를 먼저 확인해 주세요.');
  preparation.start({
    delay:reducedMotion()?0:PREPARATION_DELAY_MS,
    onStart(){preparationError=null;preparing={caseId:c.id};tab='draft';render();},
    work(){
      if(selectedId!==c.id||view!=='cases'||tab!=='draft'||!cases.includes(c))throw Error('사건 화면이 바뀌어 준비를 중단했어요.');
      const updated=structuredClone(c);generateDraft(updated);return updated;
    },
    onReady(){if(preparing?.caseId===c.id){preparing.ready=true;render();}},
    onSuccess(updated){Object.assign(c,updated);preparing=null;persist();render();notify('규칙 기반 데모 초안을 준비했어요. 직접 검토해 주세요.');},
    onError(error){preparing=null;preparationError={caseId:c.id,message:error.message};render();notify(error.message);},
    onCancel(){preparing=null;}
  });
}
function renderCasePanel(c){
  if(preparing?.caseId===c.id)return doriView(c.goal,{still:reducedMotion(),ready:preparing.ready});
  const error=preparationError?.caseId===c.id?`<div class="notice red" role="alert">${esc(preparationError.message)} 기존 사건 기록은 유지됩니다. 다시 준비할 수 있어요.</div>`:'';
  return error+({evidence:renderEvidence,policy:renderPolicy,draft:renderDraft,replies:renderReplies,history:renderHistory}[tab](c));
}
function persist(){if(storageError)return;try{saveCases(localStorage,cases);}catch{storageError='저장 공간을 사용할 수 없어요. 지금 변경은 이 화면에서만 유지됩니다.';notify(storageError);}}
function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),4200);}
function phase(c){const [label,tone]=PHASES[c.phase];return `<span class="pill ${tone}">${label}</span>`;}
function formatDate(value){return value?new Intl.DateTimeFormat('ko-KR',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(value)): '미확인';}
function formatTime(value){return new Intl.DateTimeFormat('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'}).format(new Date(value))+' KST';}
function vendorName(c){return c.vendor==='other'?(c.vendorName||'다른 판매처'):VENDORS[c.vendor];}
function dateStatus(d){const diff=Math.round((Date.parse(d.date+'T12:00:00Z')-Date.parse(dateOnly()+'T12:00:00Z'))/86400000);return diff<0?'기준일 지남':diff===0?'기준일 오늘':`${diff}일 남음`;}
function render(){
  const active=cases.filter(c=>!isClosed(c)),needs=active.filter(c=>missingEvidence(c).length&&c.phase==='preparing'),confirm=active.filter(c=>['review','refundPending','followup','manual'].includes(c.phase));
  app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-action="home"><span class="brand-mark" aria-hidden="true"><img src="./dori-mark.svg" alt="" width="38" height="38"></span>리턴데스크</a><div class="eyebrow">WORKSPACE</div><nav aria-label="주 메뉴"><button class="side-button ${view==='cases'?'active':''}" data-action="home">${icon('cases')}내 사건</button><button class="side-button ${view==='tasks'?'active':''}" data-action="tasks">${icon('calendar')}기한·대기 확인</button></nav><div class="side-bottom"><span class="pill">DEMO WORKSPACE</span><button class="side-button" data-action="about">${icon('info')}시제품 안내</button><p class="side-note">팀장 방승훈 · 팀원 오정훈<br>해외직구 교환·반품·AS</p></div></aside><div class="main-shell"><header class="topbar"><span class="breadcrumb">내 작업공간 / ${view==='cases'?'사건 관리':'기한·대기 확인'}</span><a class="brand mobile-brand" href="#" data-action="home"><span class="brand-mark" aria-hidden="true"><img src="./dori-mark.svg" alt="" width="38" height="38"></span>리턴데스크</a><div class="top-right"><button class="connection" data-action="about">${icon('shield')}AI 미연결</button><span class="small muted date-label">${formatDate(dateOnly())}</span><span class="avatar" aria-label="데모 작업공간">DE</span></div></header><main id="main" class="workspace"><div class="page-heading"><div><h1>${view==='cases'?'내 사건':'기한·대기 확인'}</h1><p>${view==='cases'?'해외직구의 다음 할 일, 한곳에서 확인하세요.':'확인한 기한과 답변을 기다리는 사건을 모았어요.'}</p></div><button class="btn primary" data-action="new">${icon('plus')}새 사건 접수</button></div><div class="demo-banner">${icon('info')}<span><b>데모 시제품</b> · 예시 사건과 규칙 기반 초안입니다. AI 호출·외부 발송은 하지 않습니다.</span><button class="dori-preview-trigger" data-action="dori-preview">도리 미리보기</button><button data-action="about">자세히 보기</button></div>${storageError?`<div class="notice red global-warning" role="alert">${esc(storageError)} <button class="btn mini" data-action="reset">초기화 확인</button></div>`:''}<div class="mobile-nav"><button class="btn ${view==='cases'?'primary':''}" data-action="home">내 사건</button><button class="btn ${view==='tasks'?'primary':''}" data-action="tasks">기한·대기</button></div>${view==='cases'?`<section class="stats" aria-label="사건 현황"><div class="stat"><span class="stat-icon">${icon('cases')}</span><div><div class="stat-label">진행 중인 사건</div><div class="stat-number">${active.length}<span>건</span></div></div></div><div class="stat"><span class="stat-icon">${icon('file')}</span><div><div class="stat-label">자료 보완 필요</div><div class="stat-number">${needs.length}<span>건</span></div></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><div class="stat-label">사용자 확인 필요</div><div class="stat-number">${confirm.length}<span>건</span></div></div></div></section><div class="case-layout">${renderList()}${selected()?renderCase(selected()):renderEmpty()}</div>`:renderTasks()}<footer class="main-footer"><span>자료는 이 브라우저에만 저장됩니다. 기기 간 동기화는 지원하지 않습니다.</span><button data-action="reset">데모 초기화</button></footer></main></div></div>`;
}
function renderList(){
  const filtered=cases.filter(c=>filter==='all'||(filter==='active'?!isClosed(c):isClosed(c)));
  return `<aside class="case-list" aria-label="사건 선택"><div class="list-head"><h2>사건 목록</h2><span class="count">${cases.length}건</span></div><div class="filter-row" aria-label="사건 필터">${[['active','진행 중'],['all','전체'],['closed','종료']].map(([id,label])=>`<button class="filter ${filter===id?'active':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div>${filtered.map(c=>`<button class="case-card ${c.id===selectedId?'active':''}" data-action="select" data-id="${esc(c.id)}" aria-pressed="${c.id===selectedId}"><span class="case-card-top"><span class="vendor-label">${esc(vendorName(c))}</span>${c.example?'<span class="pill blue">예시</span>':''}</span><span class="case-product">${esc(c.title)}</span><span class="small muted">${GOALS[c.goal]} · ${formatDate(c.received)} 수령</span><span class="case-card-bottom">${phase(c)}<span class="case-meta">${c.example?'DEMO':'내 사건'}</span></span><span class="case-next">${esc(nextAction(c).title)}</span></button>`).join('')||'<div class="list-empty">해당 상태의 사건이 없어요.</div>'}<p class="storage-note">${icon('shield')}실제 주문·카드·계좌 정보 대신<br>가림 처리한 자료로 사용하세요.</p><div class="mobile-select"><label for="case-select">사건 선택</label><select id="case-select">${cases.map(c=>`<option value="${esc(c.id)}" ${c.id===selectedId?'selected':''}>${c.example?'[예시] ':''}${esc(c.title)} · ${PHASES[c.phase][0]}</option>`).join('')}</select></div></aside>`;
}
function renderEmpty(){return `<section class="case-content"><div class="empty-state"><div class="empty-icon">${icon('box')}</div><h3>첫 사건을 접수해 보세요</h3><p>상품과 문제를 기록하면 자료 확인부터 다음 할 일을 정리할 수 있어요.</p><button class="btn primary" data-action="new">새 사건 접수</button></div></section>`;}
const tabs=[['evidence','자료 확인'],['policy','정책 근거'],['draft','문의 초안'],['replies','판매처 답변'],['history','진행 기록']];
function renderCase(c){
  const action=nextAction(c);
  return `<section class="case-content" aria-label="선택한 사건"><div class="case-header"><div class="case-kicker">${icon('box')}<span>${esc(vendorName(c))}</span><span>· ${GOALS[c.goal]}</span>${c.example?'<span class="pill blue">예시 사건</span>':''}</div><div class="case-title-row"><h2>${esc(c.title)}</h2>${phase(c)}</div><div class="case-facts"><span>수령일 <b>${esc(c.received)}</b></span><span>구매 경로 <b>${{direct:'공식 직접 구매',reseller:'제3자 판매처',unknown:'확인 필요'}[c.channel]}</b></span><span>사용 국가 <b>${{KR:'한국',US:'미국',unknown:'확인 필요'}[c.region]}</b></span></div></div><div class="next-step"><span class="next-step-icon">${icon(c.phase==='refundPending'?'check':'cases')}</span><div class="next-step-content"><h3>${esc(action.title)}</h3><p>${esc(action.detail)}</p></div><button class="btn mini" data-action="next" data-tab="${action.tab}">${action.label}</button></div><div class="tabs" role="tablist" aria-label="사건 처리 단계">${tabs.map(([id,label])=>`<button id="tab-${id}" class="tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" aria-controls="case-panel" tabindex="${tab===id?'0':'-1'}" data-action="tab" data-tab="${id}">${label}${id==='evidence'?`<span class="number">${c.evidence.filter(e=>e.ready).length}/${c.evidence.length}</span>`:id==='replies'?`<span class="number">${c.replies.length}</span>`:''}</button>`).join('')}</div><div id="case-panel" class="panel" role="tabpanel" aria-labelledby="tab-${tab}" aria-busy="${preparing?.caseId===c.id}">${renderCasePanel(c)}</div></section>`;
}
function renderEvidence(c){
  const ready=c.evidence.filter(e=>e.required&&e.ready).length,total=c.evidence.filter(e=>e.required).length;
  return `<div class="section-head"><div><h3>문의에 필요한 자료</h3><p>자료를 보유하고 있는지 직접 확인해 주세요.</p></div><span class="progress-text">필수 ${ready}/${total} 완료</span></div><progress class="progress" value="${ready}" max="${total||1}" aria-label="필수 자료 준비 상태"></progress>${c.evidence.map(e=>{
    const file=sessionFiles.get(c.id+':'+e.id);
    return `<div class="evidence-item ${e.ready?'ready':''}"><label class="check-control"><input type="checkbox" data-evidence="${e.id}" ${e.ready?'checked':''} ${isClosed(c)?'disabled':''}><span><span class="evidence-label">${esc(e.label)}<span class="required">${e.required?'필수':'선택'}</span></span><p>${esc(e.note)}</p>${file?`<span class="file-meta">${icon('file')}${esc(file.file.name)} · 화면에만 선택됨</span>`:e.ready?`<span class="file-meta">${c.example?'보유 확인 예시 · 실제 파일 없음':'보유 확인됨 · 이 화면에 선택한 파일 없음'}</span>`:''}</span></label>${!isClosed(c)?`<span class="upload-wrap"><input class="upload-input" type="file" id="file-${e.id}" data-file="${e.id}" accept="image/png,image/jpeg,image/webp,application/pdf"><label class="btn mini subtle" for="file-${e.id}">${icon('upload')}파일 선택</label></span>`:''}${file?.url?`<button class="btn mini ghost" data-action="preview" data-evidence="${e.id}">미리보기</button>`:''}</div>`;
  }).join('')}<p class="panel-note">JPG·PNG·WebP·PDF, 파일당 최대 10MB. 파일은 업로드·분석·전송하지 않습니다. 새로고침하면 다시 선택해야 하며 보유 확인 목록만 저장됩니다.</p><div class="panel-footer"><p>주문 번호 외 주소·결제 정보는 가려 주세요.</p><button class="btn primary" data-action="generate" ${isClosed(c)?'disabled':''}>문의 초안 준비</button></div>`;
}
function renderPolicy(c){
  const p=POLICIES[c.vendor],d=deadline(c);
  if(!p||!applicablePolicy(c))return `<div class="notice">${!p?'이 판매처의 공식 정책은 아직 등록되지 않았어요.':'제3자 구매 또는 구매 경로 미확인 상태입니다. 제조사 직접 구매 정책을 그대로 적용하지 않습니다.'}</div><div class="empty-state"><div class="empty-icon">${icon('shield')}</div><h3>정책 적용 여부 확인이 필요해요</h3><p>구매한 판매처의 원문과 구매 조건을 직접 확인해 주세요. 자료가 모이면 가능 여부를 묻는 데모 문의 초안을 만들 수 있습니다.</p><button class="btn" data-action="tab" data-tab="draft">문의 초안 보기</button></div>`;
  return `<div class="section-head"><div><h3>공식 정책과 적용 조건</h3><p>출처를 확인해도 개별 사건의 적용 여부는 따로 검토해야 해요.</p></div></div><div class="policy-card"><div class="policy-source"><div><h3>${p.title}</h3><p>개발 시 원문 조회 · ${POLICY_DATE} UTC · 자동 재조회 아님</p></div><a class="btn mini" href="${p.url}" target="_blank" rel="noopener noreferrer">${icon('link')}원문 열기</a></div><p>${p.summary}</p><blockquote lang="en">${p.quote}</blockquote><p class="small muted">원문 항목: ${c.vendor==='apple'?'Standard Return Policy':'Warranty Claims → Process'}</p></div><div class="notice">${p.caution}</div><label class="policy-check"><input type="checkbox" id="policy-check" ${c.policyConfirmed?'checked':''} ${isClosed(c)?'disabled':''}><span>원문과 구매 경로·국가·상품 조건을 직접 검토했어요.<small>사용자 검토 기록이며 반품·교환·보증 승인이나 최신 정책 확인을 대신하지 않습니다.</small></span></label>${d?`<div class="notice blue stale"><b>${esc(d.kind)} · ${esc(d.date)}</b><br>${esc(d.basis)}<br><span class="small">기준 시간대 ${esc(d.zone)} · ${d.confirmed?'판매처 원문을 사용자가 기록':'자동 성공·기한 확정 없음'}</span></div>`:''}`;
}
function renderDraft(c){
  if(!c.draft)return `<div class="section-head"><div><h3>한국어로 확인하고, 영어로 문의하세요</h3><p>확인한 사실로 영문 문의 틀을 채웁니다.</p></div><span class="pill blue">규칙 기반 데모</span></div><div class="draft-summary"><b>이 사건의 요청</b><p>${GOALS[c.goal]} · ${esc(c.issue)}</p></div><div class="notice blue">AI가 연결되지 않았습니다. 미리 정의한 영문 문의 틀을 사용하며 자유 입력 내용의 자동 번역·분석은 수행하지 않습니다.</div><div class="empty-state"><div class="empty-icon">${icon('file')}</div><h3>${missingEvidence(c).length?'필수 자료를 먼저 확인해 주세요':'첫 문의 초안을 준비할 수 있어요'}</h3><p>${missingEvidence(c).length?`남은 자료: ${esc(missingEvidence(c).map(e=>e.label).join(', '))}`:'정책이 미확인이라면 적용 가능 여부와 필요한 절차를 묻는 내용으로 작성합니다.'}</p><button class="btn primary" data-action="${missingEvidence(c).length?'tab':'generate'}" data-tab="evidence" ${isClosed(c)?'disabled':''}>${missingEvidence(c).length?'자료 확인하기':'데모 초안 만들기'}</button></div>`;
  return `<div class="section-head"><div><h3>문의 초안 검토</h3><p>사실·요청 조치·첨부 목록을 직접 확인하세요.</p></div><span class="pill blue">규칙 기반 데모</span></div>${c.draftStale?'<div class="notice" id="stale-notice">자료·정책·답변이 바뀌었어요. 초안을 다시 만든 뒤 검토해 주세요.</div>':''}<div class="draft-summary"><b>한국어 확인 요약</b><p>요청: ${GOALS[c.goal]} · ${esc(c.title)}<br>문제: ${esc(c.issue)}<br>정책 적용: ${c.policyConfirmed?'사용자가 조건 검토를 기록함':'확인 필요 · 가능 여부를 문의'}<br>보유 자료: ${esc(c.evidence.filter(e=>e.ready).map(e=>e.label).join(', '))||'없음'}</p></div><label class="field-label" for="draft-editor">영문 문의 초안 · 직접 수정 가능</label><textarea id="draft-editor" class="draft-editor" ${isClosed(c)?'readonly':''} maxlength="12000" spellcheck="false" lang="en">${esc(c.draft)}</textarea><p id="review-label" class="review-label">${c.reviewed?'현재 내용의 검토를 완료했어요.':'내용을 수정하면 이전 검토 기록은 무효화됩니다.'}</p><label class="review-check"><input id="review-check" type="checkbox" ${c.reviewed?'checked':''} ${c.draftStale||isClosed(c)?'disabled':''}><span>상품·문제·정책 미확인 사항과 첨부할 자료를 확인했고, 이 초안 내용을 검토했어요.</span></label><div class="draft-actions"><button class="btn" data-action="generate" ${isClosed(c)?'disabled':''}>다시 만들기</button><button class="btn" id="copy-button" data-action="copy" ${!c.reviewed||c.draftStale?'disabled':''}>${icon('copy')}초안 복사</button><button class="btn primary" id="submitted-button" data-action="submission" ${!c.reviewed||c.draftStale||isClosed(c)?'disabled':''}>직접 제출 기록</button></div><p class="panel-note">이 앱에서는 발송하지 않습니다. 공식 문의 경로에서 직접 제출하고 관련 자료를 첨부하세요. 영문 틀의 자유 입력 내용은 자동 번역되지 않습니다.</p>`;
}
function renderReplies(c){
  return `<div class="section-head"><div><h3>판매처 답변과 후속 조치</h3><p>새로운 요청을 기록하면 필요한 자료와 상태가 바뀝니다.</p></div>${!isClosed(c)?`<button class="btn mini primary" data-action="reply">${icon('plus')}답변 추가</button>`:''}</div>${c.phase==='refundPending'?`<div class="result-box"><h3>환불 통지 기록 · 실제 입금은 미확인</h3><p>판매처의 환불 처리 통지만으로 사건을 종료하지 않습니다. 원래 결제 수단에서 직접 확인해 주세요.</p><button class="btn" data-action="complete">실제 입금 확인 기록</button></div>`:c.phase==='followup'?`<div class="notice blue"><b>교환·AS 후속 처리 안내가 있어요.</b><br>실제 교환품 수령 또는 수리 결과를 확인한 뒤 종료하세요.<br><button class="btn mini stale" data-action="complete">처리 결과 확인 기록</button></div>`:c.phase==='manual'?'<div class="notice">판매처 거절·조건 충돌·불명확한 답변을 확인하세요. 추가 자료로 재문의하거나 진행 기록에서 수동 전환할 수 있습니다.</div>':''}${!isClosed(c)?`<div class="demo-sample"><span>답변 변화 체험</span><button class="btn mini subtle" data-action="reply" data-sample="evidence">예시 추가 자료 요청</button><button class="btn mini subtle" data-action="reply" data-sample="refund">예시 환불 통지</button></div>`:''}${c.replies.length?c.replies.map(r=>`<article class="reply-card"><div class="reply-card-top"><span class="pill ${r.type==='refund'?'purple':'slate'}">${REPLY_TYPES[r.type][0]}</span><span class="small muted">${r.example?'예시 답변 · ':''}${formatTime(r.at)}</span></div><pre>${esc(r.text)}</pre><p class="panel-note">${r.example?'가상 판매처 답변입니다. 실제 연락 또는 환불 결과가 아닙니다.':'답변 유형은 사용자가 선택했습니다. 자동 AI 분석 결과가 아닙니다.'}</p></article>`).join(''):`<div class="empty-state"><div class="empty-icon">${icon('reply')}</div><h3>아직 기록한 답변이 없어요</h3><p>가림 처리한 판매처 답변을 붙여 넣고 변경 유형을 선택하세요. 예시 답변으로도 흐름을 체험할 수 있어요.</p></div>`}`;
}
function renderHistory(c){return `<div class="section-head"><div><h3>사건의 진행 기록</h3><p>판단 근거와 사용자 확인을 구분해 보관합니다.</p></div><span class="count">${c.events.length}개 기록</span></div>${c.example?'<div class="legend"><span class="pill blue">예시 사건</span>진행 기록도 데모 체험이며 실제 외부 처리 결과가 아닙니다.</div>':''}<ol class="timeline">${c.events.map(e=>`<li><div class="timeline-title">${esc(e.title)}</div><p>${esc(e.detail)}</p><time datetime="${esc(e.at)}">${formatTime(e.at)}</time></li>`).join('')}</ol>${!isClosed(c)?'<div class="history-footer"><button class="btn danger mini" data-action="stop">수동 전환·중단 기록</button></div>':''}`;}
function renderTasks(){const open=cases.filter(c=>!isClosed(c));return `<div class="notice blue">판매처 답변에 명시된 기한과 원문 근거를 함께 기록합니다. Apple 일반 반품 참고일은 적용 조건을 사용자가 검토한 반품 사건에서만 계산합니다. 답변 지연으로 자동 종료하지 않습니다.</div><section class="tasks-grid" aria-label="기한 및 대기 사건">${open.map(c=>{const d=deadline(c);return `<article class="task-card"><span class="vendor-label">${c.example?'예시 · ':''}${esc(vendorName(c))}</span><h3>${esc(c.title)}</h3>${d?`<div class="task-date">${formatDate(d.date)} <span class="small">${dateStatus(d)}</span></div><p>${esc(d.kind)} · ${esc(d.zone)}</p><div class="task-basis">${esc(d.basis)}</div>`:`<p>${esc(nextAction(c).title)}</p><div class="task-basis">확인된 기한 없음 · 날짜를 임의로 추정하지 않습니다.</div>`}${phase(c)}<div class="stale"><button class="btn mini" data-action="open-task" data-id="${esc(c.id)}">사건 확인하기</button></div></article>`;}).join('')||renderEmpty()}</section>`;}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="창 닫기">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.showModal();modal.querySelector('[autofocus]')?.focus();}
function errorInForm(message){let el=modal.querySelector('.form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');modal.querySelector('.modal-body').append(el);}el.textContent=message;}
function doriPreviewModal(){
  previewStill=reducedMotion();const goal=selected()?.goal||'return';
  showModal('도리 미리보기',`<div id="dori-modal-stage" data-goal="${goal}">${doriView(goal,{preview:true,still:previewStill})}</div><div class="dori-preview-controls"><button class="btn mini" data-action="dori-motion" aria-pressed="${previewStill}" ${reducedMotion()?'disabled':''}>${previewStill?'움직임 켜기':'움직임 끄기'}</button><a class="btn mini" href="./dori-preview.html" target="_blank" rel="noopener">독립 미리보기</a></div><p class="panel-note">시스템의 모션 줄이기 설정도 따릅니다. 실제 파일 분석·AI 호출·외부 발송은 없습니다.</p>`);
}
function newCaseModal(){showModal('새 사건 접수',`<p class="modal-subtitle">확인한 정보만 입력하세요. 이름·이메일·주소·카드·계좌 정보는 받지 않습니다.</p><form id="new-case-form"><div class="form-grid"><div class="field full"><label class="field-label" for="title">상품명 <span class="required">필수</span></label><input id="title" name="title" required maxlength="100" placeholder="예: Anker 65W 충전기" autofocus></div><fieldset class="radio-group full"><legend class="field-label">원하는 조치</legend><div class="radio-options">${Object.entries(GOALS).map(([id,label])=>`<label class="radio-card"><input type="radio" name="goal" value="${id}" ${id==='return'?'checked':''}>${label}</label>`).join('')}</div></fieldset><div class="field"><label class="field-label" for="vendor">판매처</label><select id="vendor" name="vendor">${Object.entries(VENDORS).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></div><div class="field"><label class="field-label" for="channel">구매 경로</label><select id="channel" name="channel"><option value="unknown">확인 필요</option><option value="direct">공식 직접 구매</option><option value="reseller">제3자 판매처</option></select></div><div class="field full hidden" id="vendor-name-field"><label class="field-label" for="vendorName">판매처 이름</label><input id="vendorName" name="vendorName" maxlength="100" placeholder="구매한 판매처의 이름"></div><div class="field"><label class="field-label" for="received">상품 수령일 <span class="required">필수</span></label><input id="received" type="date" name="received" required max="${dateOnly()}" value="${dateOnly()}"></div><div class="field"><label class="field-label" for="region">현재 상품 사용 국가</label><select id="region" name="region"><option value="KR">한국</option><option value="US">미국</option><option value="unknown">확인 필요</option></select></div><div class="field"><label class="field-label" for="order">가림 처리한 주문 참조 (선택)</label><input id="order" name="order" maxlength="100" placeholder="예: ORDER-****1234"></div><div class="field"><label class="field-label" for="issueType">문제 유형</label><select id="issueType" name="issueType">${Object.entries(ISSUES).map(([id,[label]])=>`<option value="${id}">${label}</option>`).join('')}</select></div><div class="field full"><label class="field-label" for="issue">문제 설명 <span class="required">필수</span></label><textarea id="issue" name="issue" required maxlength="1500" placeholder="어떤 문제가 있었는지 확인한 사실을 적어 주세요."></textarea></div><div class="field full"><label class="field-label" for="issueEnglish">직접 작성한 영문 증상 (선택)</label><input id="issueEnglish" name="issueEnglish" maxlength="1500" placeholder="예: Charging does not start."><small>입력하지 않으면 문제 유형의 정해진 영문 문장과 한국어 원문을 사용합니다.</small></div></div><p class="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="close">취소</button><button class="btn primary" type="submit">사건 접수하기</button></div></form>`);}
function replyModal(sample){const c=selected(),example=!!sample;
  const texts={evidence:'[예시 답변] Thank you for contacting us. Please provide a clear photo of the product serial number and a photo showing the issue.',refund:'[예시 답변] Your refund has been processed. Please check your original payment method. Posting times may vary.'};
  showModal('판매처 답변 추가',`<p class="modal-subtitle">${example?'가상 답변으로 상태 변화를 체험합니다. 실제 문의·환불 결과가 아닙니다.':'개인정보를 가린 답변만 붙여 넣으세요. 데모에서는 변경 유형을 직접 선택합니다.'}</p><form id="reply-form" data-example="${example}"><div class="form-grid"><div class="field full"><label class="field-label" for="reply-text">답변 내용 <span class="required">필수</span></label><textarea id="reply-text" name="text" required maxlength="8000" autofocus>${esc(texts[sample]||'')}</textarea></div><div class="field full"><label class="field-label" for="reply-type">답변으로 달라진 점</label><select id="reply-type" name="type">${Object.entries(REPLY_TYPES).map(([id,[label]])=>`<option value="${id}" ${id===(sample||'evidence')?'selected':''}>${label}</option>`).join('')}</select></div><div class="full ${sample==='refund'?'hidden':''}" id="requested-evidence"><span class="field-label">요청받은 자료</span><div class="checkbox-list">${c.evidence.map(e=>`<label><input type="checkbox" name="evidenceIds" value="${e.id}" ${sample==='evidence'&&['serial','photo'].includes(e.id)?'checked':''}>${esc(e.label)}</label>`).join('')}</div></div><div class="full change-preview" id="change-preview">${PHASES[c.phase][0]} → ${REPLY_TYPES[sample||'evidence'][0]}</div><div class="field full"><label class="field-label" for="reply-deadline">판매처가 명시한 기한 (선택)</label><input type="date" id="reply-deadline" name="deadline"><small>명시된 날짜가 없다면 비워 두세요. 시간대와 원문 근거도 함께 기록합니다.</small></div><div class="field"><label class="field-label" for="deadline-zone">기한의 시간대</label><select id="deadline-zone" name="zone"><option value="UTC">UTC</option><option value="America/Los_Angeles">미국 태평양</option><option value="America/New_York">미국 동부</option><option value="Asia/Seoul">한국</option></select></div><div class="field"><label class="field-label" for="deadline-quote">기한 원문 근거</label><input id="deadline-quote" name="deadlineQuote" maxlength="500" placeholder="판매처가 적은 날짜 문장"></div></div><p class="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="close">취소</button><button class="btn primary" type="submit">답변과 상태 반영</button></div></form>`);
}
function confirmation(kind){const c=selected(),refund=c.phase==='refundPending';const labels={submission:['직접 제출 사실 기록','공식 문의 경로에서 직접 제출했고, 필요한 파일도 직접 첨부했어요.','제출 기록하기'],complete:[refund?'실제 입금 확인 기록':'최종 처리 결과 확인',refund?'은행·카드 거래 내역에서 실제 입금을 직접 확인했어요.':'교환품 수령 또는 수리 결과를 직접 확인했어요.','확인하고 사건 종료']};const [title,text,button]=labels[kind];showModal(title,`<form id="confirmation-form" data-kind="${kind}">${c.example?'<div class="notice blue">예시 사건입니다. 이 확인은 데모 상태를 바꾸며 실제 외부 처리 결과를 기록한 것으로 해석하지 않습니다.</div>':'<p class="modal-subtitle">사용자가 직접 확인한 사실만 기록합니다.</p>'}<label class="review-check"><input type="checkbox" name="confirmed" required><span>${text}</span></label><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary" type="submit">${button}</button></div></form>`);}
function about(){showModal('리턴데스크 시제품 안내',`<div class="about-detail"><p><b>사건 관리 흐름을 직접 체험하는 데모입니다.</b><br>사건 접수, 자료 보유 확인, 공식 정책 출처, 문의 초안 검토, 판매처 답변과 종료 확인을 연결합니다.</p><p><b>AI 연결 상태: 미연결</b><br>새 키 설정은 별도로 진행 중입니다. 현재 초안은 정해진 영문 틀이며 AI 판단·번역 결과가 아닙니다. 문서와 답변을 자동 분석하지 않습니다.</p><p><b>데이터 보관</b><br>내용과 체크 목록은 이 브라우저의 저장 공간에만 남습니다. 선택한 파일은 서버로 전송하지 않으며 새로고침하면 다시 선택해야 합니다. 같은 계정이라도 PC와 휴대폰 사이에 동기화되지 않습니다.</p><p><b>외부 처리</b><br>문의 발송·환불·결제·판매처 로그인·은행 조회는 수행하지 않습니다. 원문 정책 링크는 외부 공식 사이트에서 열립니다.</p><p class="small muted">팀장 방승훈 · 팀원 오정훈<br>기획서 작성 2026.10.05–10.11 · 제출 10.12<br>개발 시 공식 정책 원문 조회: ${POLICY_DATE} UTC</p></div>`);}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();const action=button.dataset.action,c=selected();try{
  if(preparation.running&&!['generate','cancel-preparation'].includes(action))cancelDraftPreparation('navigation');
  if(action==='cancel-preparation'){cancelDraftPreparation('user',true);return;}
  if(action==='close'){modal.close();modal.innerHTML='';return;}
  if(action==='dori-preview'){doriPreviewModal();return;}
  if(action==='dori-motion'){previewStill=!previewStill;const stage=modal.querySelector('#dori-modal-stage');stage.innerHTML=doriView(stage.dataset.goal,{preview:true,still:previewStill||reducedMotion()});button.textContent=previewStill?'움직임 켜기':'움직임 끄기';button.setAttribute('aria-pressed',String(previewStill));return;}
  if(action==='new'){newCaseModal();return;}if(action==='about'){about();return;}
  if(action==='reset'){showModal('데모 초기화',`<form id="reset-form"><div class="notice">이 브라우저에 저장한 모든 사건·수정·진행 기록이 삭제되고 처음의 예시 3건으로 돌아갑니다.</div><label class="review-check"><input type="checkbox" name="confirmed" required>저장된 데이터를 삭제하고 예시로 되돌리는 데 동의해요.</label><div class="form-actions"><button type="button" class="btn" data-action="close">취소</button><button class="btn danger" type="submit">초기화하기</button></div></form>`);return;}
  if(action==='home'){view='cases';render();return;}if(action==='tasks'){view='tasks';render();return;}
  if(action==='filter'){filter=button.dataset.value;const visible=cases.filter(c=>filter==='all'||(filter==='active'?!isClosed(c):isClosed(c)));if(!visible.some(c=>c.id===selectedId))selectedId=visible[0]?.id||'';render();return;}
  if(action==='select'||action==='open-task'){selectedId=button.dataset.id;view='cases';tab='evidence';render();return;}
  if(!c)return;
  if(action==='tab'||action==='next'){tab=button.dataset.tab;render();if(action==='tab')document.querySelector(`#tab-${tab}`)?.focus();return;}
  if(action==='generate'){startDraftPreparation(c);return;}
  if(action==='copy'){if(!c.reviewed||c.draftStale)throw Error('현재 초안을 먼저 검토해 주세요.');try{await navigator.clipboard.writeText(c.draft);logEvent(c,'검토한 초안 복사',c.example?'예시 초안 복사 · 실제 발송 없음':'사용자가 직접 제출할 수 있도록 복사');persist();notify('초안을 복사했어요. 공식 문의 경로에서 직접 제출하세요.');}catch{const editor=document.querySelector('#draft-editor');editor.focus();editor.select();notify('복사 권한을 사용할 수 없어요. 선택된 글을 직접 복사해 주세요.');}return;}
  if(action==='submission'){confirmation('submission');return;}if(action==='complete'){confirmation('complete');return;}
  if(action==='reply'){replyModal(button.dataset.sample);return;}
  if(action==='stop'){showModal('수동 전환·중단 기록',`<form id="stop-form"><p class="modal-subtitle">현재 자료를 보존하고 직접 처리할 수 있도록 이유를 남겨 주세요.</p><div class="field"><label class="field-label" for="stop-reason">전환 또는 중단 사유</label><textarea id="stop-reason" name="reason" required maxlength="1000" placeholder="예: 판매처 조건이 불명확해 직접 문의하기로 결정" autofocus></textarea></div><div class="form-actions"><button type="button" class="btn" data-action="close">취소</button><button class="btn danger" type="submit">사유 기록하고 수동 전환</button></div></form>`);return;}
  if(action==='preview'){const file=sessionFiles.get(c.id+':'+button.dataset.evidence);if(file?.url)showModal('선택한 자료 · 로컬 미리보기',`<img class="preview-img" src="${file.url}" alt="선택한 증빙 사진"><p class="panel-note">${esc(file.file.name)} · 이 파일은 업로드·전송되지 않습니다.</p>`);}
}catch(error){notify(error.message);}});
document.addEventListener('change',event=>{const el=event.target,c=selected();try{
  if(preparation.running){cancelDraftPreparation('data-change');render();}
  if(el.id==='case-select'){selectedId=el.value;tab='evidence';render();return;}
  if(el.id==='vendor'){document.querySelector('#vendor-name-field').classList.toggle('hidden',el.value!=='other');document.querySelector('#vendorName').required=el.value==='other';return;}
  if(el.id==='reply-type'){document.querySelector('#requested-evidence').classList.toggle('hidden',el.value!=='evidence');document.querySelector('#change-preview').textContent=`${PHASES[c.phase][0]} → ${PHASES[REPLY_TYPES[el.value][1]][0]} · ${REPLY_TYPES[el.value][0]}`;return;}
  if(!c)return;
  if(el.matches('input[data-evidence]')){const evidence=c.evidence.find(e=>e.id===el.dataset.evidence);evidence.ready=el.checked;invalidateDraft(c);if(c.phase==='review')c.phase='preparing';logEvent(c,'자료 보유 확인 변경',`${evidence.label}: ${el.checked?'보유 확인':'확인 필요'}`);persist();render();return;}
  if(el.id==='policy-check'){c.policyConfirmed=el.checked;invalidateDraft(c);logEvent(c,'정책 조건 사용자 검토',el.checked?'원문과 적용 조건을 검토했다고 기록 · 판매처 승인 아님':'정책 적용 조건 다시 확인 필요');persist();render();return;}
  if(el.id==='review-check'){if(el.checked)approveDraft(c);else{c.reviewed=false;logEvent(c,'초안 검토 취소');}persist();render();return;}
  if(el.matches('input[data-file]')){const file=el.files[0];if(!file)return;if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))throw Error('JPG·PNG·WebP·PDF, 10MB 이하 파일을 선택해 주세요.');const key=c.id+':'+el.dataset.file;const prior=sessionFiles.get(key);if(prior?.url)URL.revokeObjectURL(prior.url);sessionFiles.set(key,{file,url:file.type.startsWith('image/')?URL.createObjectURL(file):null});const evidence=c.evidence.find(e=>e.id===el.dataset.file);evidence.ready=true;invalidateDraft(c);if(c.phase==='review')c.phase='preparing';logEvent(c,'로컬 자료 선택',`${evidence.label} · 파일은 서버로 전송되지 않음`);persist();render();notify('이 화면에서 파일을 선택했어요. 업로드·분석은 하지 않습니다.');}
}catch(error){notify(error.message);if(el.type==='file')el.value='';}});
document.addEventListener('input',event=>{if(event.target.id!=='draft-editor')return;const c=selected();c.draft=event.target.value;c.reviewed=false;document.querySelector('#review-check').checked=false;document.querySelector('#copy-button').disabled=true;document.querySelector('#submitted-button').disabled=true;document.querySelector('#review-label').textContent='내용이 바뀌었어요. 현재 초안을 다시 검토해 주세요.';persist();});
document.addEventListener('keydown',event=>{if(!event.target.matches('[role="tab"]'))return;const current=tabs.findIndex(([id])=>id===tab);let next=current;if(event.key==='ArrowRight')next=(current+1)%tabs.length;else if(event.key==='ArrowLeft')next=(current+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();cancelDraftPreparation('keyboard-navigation');tab=tabs[next][0];render();document.querySelector('#tab-'+tab).focus();});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,data=new FormData(form);try{
  if(form.id==='new-case-form'){if(cases.length>=100)throw Error('이 시제품은 최대 100개의 사건을 보관합니다.');const c=createCase(Object.fromEntries(data));cases.unshift(c);selectedId=c.id;view='cases';filter='active';tab='evidence';notify('새 사건을 접수했어요. 필수 자료를 확인해 주세요.');}
  else if(form.id==='reply-form'){addReply(selected(),{...Object.fromEntries(data),evidenceIds:data.getAll('evidenceIds'),example:form.dataset.example==='true'});tab='replies';notify('답변 유형에 맞춰 사건 상태를 반영했어요.');}
  else if(form.id==='confirmation-form'){if(!data.has('confirmed'))throw Error('직접 확인한 사실에 체크해 주세요.');if(form.dataset.kind==='submission')recordSubmission(selected());else completeCase(selected(),true);tab='history';filter='all';notify(form.dataset.kind==='submission'?'직접 제출 사실을 기록했어요. 앱에서 발송하지 않았습니다.':'사용자 확인을 기록하고 사건을 종료했어요.');}
  else if(form.id==='stop-form'){const reason=data.get('reason')?.trim();if(!reason)throw Error('전환 사유를 입력해 주세요.');const c=selected();c.phase='stopped';c.stopReason=reason;invalidateDraft(c);logEvent(c,'수동 전환·중단',reason);filter='all';tab='history';notify('사유를 남기고 수동 전환했어요.');}
  else if(form.id==='reset-form'){if(!data.has('confirmed'))throw Error('데이터 초기화에 동의하는 항목을 확인해 주세요.');for(const f of sessionFiles.values())if(f.url)URL.revokeObjectURL(f.url);sessionFiles.clear();storageError='';cases=seedCases();selectedId=cases[0].id;filter='active';tab='evidence';view='cases';notify('처음의 예시 사건으로 초기화했어요.');}
  else return;
  persist();modal.close();render();
}catch(error){errorInForm(error.message);}});
modal.addEventListener('close',()=>{if(!modal.open)modal.innerHTML='';});
document.defaultView?.addEventListener('pagehide',()=>{if(cancelDraftPreparation('pagehide'))render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&cancelDraftPreparation('hidden'))render();});
render();
